"use strict";
const assert = require("node:assert/strict");
const fs = require("node:fs");
const ui = fs.readFileSync("app/(admin)/assistance-requests.tsx", "utf8");
const backend = fs.readFileSync("backend/server.js", "utf8");
const support = ui.slice(ui.indexOf('const donationCampaignReady ='),ui.indexOf('const [privateAddressSearch',ui.indexOf('const donationCampaignReady =')));
const button = ui.slice(ui.indexOf('A Donation Campaign is already linked'),ui.indexOf('["internal_support", "not_required"]',ui.indexOf('A Donation Campaign is already linked')));
assert(support.includes('request.supportDecision === "donation_support"'),"Cannot publish without Donation Support decision");
assert(support.includes('Number(request.remainingAmount || 0) > 0'),"Requires an unmet verified monetary need");
assert(support.includes('request.assignedLocationName'),"Requires official public location");
assert(support.includes('request.assignedLocationAddress'),"Requires official service address");
assert(support.includes('pathname: "/donation-list"'),"CTA must navigate to existing donation workflow, not publish directly");
assert(button.includes('donationCampaignReady || request.donationCampaignId'),"CTA gated on readiness or existing campaign");
assert(button.includes('label={request.donationCampaignId ? "View Published Campaign" : "Continue to Publish"}'),"Accessible red CTA label missing");
assert(button.includes('variant={request.donationCampaignId ? "primary" : "publish"}'),"Red publish variant only for draft campaign continuation");
assert(button.includes('onPress={openDonationCampaign}'),"Publish CTA must use existing guarded navigation");
assert(button.includes("This request is not public until"),"Clear distinction between Verify and Publish needed");
assert(ui.includes('backgroundColor: "#B42318"') && ui.includes('textColor: "#FFFFFF"'),"Solid red Publish button required");
assert(backend.includes('verified_assistance_required'),"Backend must enforce verified review");
assert(backend.includes('donation_support_not_approved'),"Backend must enforce support decision");
assert(backend.includes('resident_public_campaign_photo_required'),"Backend must enforce resident public photo consent");
assert(backend.includes('funding_goal_must_match_verified_shortage'),"Backend must prevent exceeding verified need");
assert(backend.includes('private_assistance_data_in_public_copy'),"Backend must protect private resident data");
console.log("PASS red Continue to Publish CTA, verified eligibility, secure navigation and backend publish safety gates");
